import { appendFileSync } from 'node:fs';

function record(event, options) {
  appendFileSync(
    process.env.FAKE_PLAYWRIGHT_LOG,
    `${JSON.stringify({ event, options })}\n`
  );
}

const cdpSession = {
  on: () => {},
  send: async method =>
    method === 'Page.getFrameTree'
      ? { frameTree: { frame: { id: 'main-frame' } } }
      : {},
};

export const chromium = {
  launch: async options => {
    record('launch', options);
    let currentUrl = 'about:blank';
    const page = {
      goto: async url => {
        currentUrl = url;
      },
      url: () => currentUrl,
    };
    const context = {
      newPage: async () => page,
      newCDPSession: async () => cdpSession,
    };
    page.context = () => context;
    return {
      newContext: async contextOptions => {
        record('newContext', contextOptions);
        return context;
      },
      close: async () => {},
    };
  },
};
